// ── 辅助函数 ──────────────────────────────────────────────────
export function getCustomerById(id: string): Customer | undefined {
  return demoCustomers.find(c => c.customerId === id);
}

export function getKYCByCustomerId(customerId: string): CustomerKYC | undefined {
  return demoKYC.find(k => k.customerId === customerId);
}

export function getProductsByLayer(layer: string): Product[] {
  return demoProducts.filter(p => p.pyramidLayer === layer && p.isActive);
}

export function getProductsByRiskLevel(riskLevel: string): Product[] {
  return demoProducts.filter(p => p.isActive && p.suitabilityScope.includes(riskLevel));
}

// ── 按产品类别统计 ──────────────────────────────────────────────
export function getProductsByCategory(): Record<string, Product[]> {
  const result: Record<string, Product[]> = {};
  for (const p of demoProducts) {
    if (!result[p.category]) result[p.category] = [];
    result[p.category].push(p);
  }
  return result;
}

// ── 按发行机构统计 ──────────────────────────────────────────────
export function getProductsByIssuer(): Record<string, Product[]> {
  const result: Record<string, Product[]> = {};
  for (const p of demoProducts) {
    if (!result[p.issuer]) result[p.issuer] = [];
    result[p.issuer].push(p);
  }
  return result;
}
